import pysam
from collections import defaultdict

FA38='/task/input/resources/GRCh38.chr22.fa.gz'
GFF='/task/input/resources/GRCh38.chr22.canonical.gff3'
POP='/task/input/resources/popfreq.GRCh38.tsv.gz'
VCF='/task/output/trio.GRCh38.vcf.gz'
FSRC='/task/work/final_source.tsv'
SRC='/task/work/source.tsv'
PANEL='/task/input/panel_genes.txt'
OUT='/task/output/candidates.tsv'
SAMPLES=['F4955-78','F4955-29','F4955-67']
DAD,MOM,KID=SAMPLES

RC=str.maketrans('ACGT','TGCA')
def rc(s): return s.translate(RC)[::-1]
CODON={}
bases='TCAG'
for i,a in enumerate(bases):
  for j,b in enumerate(bases):
    for k,c in enumerate(bases):
      CODON[a+b+c]='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'[i*16+j*4+k]

# ---- GFF3
gene_name={}
mRNA={}  # tid -> gene symbol
cds=defaultdict(list)
exons=defaultdict(list)
strand={}
for line in open(GFF):
    if line.startswith('#'): continue
    f=line.rstrip('\n').split('\t')
    if len(f)<9: continue
    typ=f[2]; s=int(f[3]); e=int(f[4]); st=f[6]; attr=f[8]
    A={}
    for kv in attr.split(';'):
        if '=' in kv:
            k,v=kv.split('=',1); A[k]=v
    if typ=='gene':
        gene_name[A['ID']]=A['Name']
    elif typ=='mRNA':
        tid=A['ID'].split(':')[1] if ':' in A['ID'] else A['ID']
        gid=A['Parent']
        mRNA[tid]=gene_name[gid]
        strand[tid]=st
    elif typ=='CDS':
        tid=A['Parent'].split(':')[1] if ':' in A['Parent'] else A['Parent']
        cds[tid].append((s-1,e))
    elif typ=='exon':
        tid=A['Parent'].split(':')[1] if ':' in A['Parent'] else A['Parent']
        exons[tid].append((s-1,e))
tids=sorted(mRNA)
for t in tids:
    cds[t].sort(); exons[t].sort()
print('transcripts:',len(tids))

# splice regions per transcript: dict tid -> list of (pos0, type) intronic 2bp and exonic 2bp at each boundary
# boundary between exon k and k+1 (genomic order)
splice=defaultdict(dict)  # tid -> pos0 -> 'donor'/'acceptor'
for t in tids:
    ex=exons[t]
    for k in range(len(ex)-1):
        e1=ex[k][1]; s2=ex[k+1][0]
        if strand[t]=='+':
            d_positions=[e1-2,e1-1,e1,e1+1]      # last 2 exon + first 2 intron
            a_positions=[s2-2,s2-1,s2,s2+1]
        else:
            a_positions=[e1-2,e1-1,e1,e1+1]
            d_positions=[s2-2,s2-1,s2,s2+1]
        for p in d_positions: splice[t][p]='donor'
        for p in a_positions: splice[t][p]='acceptor'

# cds position index per transcript
cdsidx={}
cdsseq={}
fa=pysam.FastaFile(FA38)
for t in tids:
    poslist=[]
    for (s,e) in cds[t]:
        poslist.extend(range(s,e))
    if strand[t]=='-':
        poslist=poslist[::-1]
    cdsidx[t]={p:i for i,p in enumerate(poslist)}
    seq=''.join(fa.fetch('chr22',p,p+1).upper() for p in poslist)
    if strand[t]=='-':
        seq=''.join({'A':'T','T':'A','G':'C','C':'G','N':'N'}[b] for b in seq)
    cdsseq[t]=seq

def consequence(pos,ref,alt,t):
    """returns (class, detail) for variant vs transcript t"""
    p0=pos-1
    # affected positions
    if len(ref)==1 and len(alt)==1:
        aff=[p0]
        kind='snv'
    elif len(ref)<len(alt) and alt.startswith(ref):
        aff=[p0,p0+1]; kind='ins'
    elif len(alt)<len(ref) and ref.startswith(alt):
        aff=list(range(p0+1,p0+len(ref))); kind='del'
    else:
        aff=list(range(p0,p0+len(ref))); kind='sub'
    sp=set()
    for p in aff:
        if p in splice[t]: sp.add(splice[t][p])
    if sp:
        if 'donor' in sp and 'acceptor' in sp: return ('splice_donor&acceptor',)
        return ('splice_donor',) if 'donor' in sp else ('splice_acceptor',)
    idx=cdsidx[t]
    if kind=='snv':
        if p0 in idx:
            i=idx[p0]; c0=(i//3)*3
            refcod=cdsseq[t][c0:c0+3]
            altcod=refcod[:i%3]+alt+refcod[i%3+1:]
            ra,aa=CODON.get(refcod,'?'),CODON.get(altcod,'?')
            if ra==aa: return ('synonymous',)
            if aa=='*': return ('stop_gained',)
            return ('missense',)
        return _noncoding(t,aff)
    if kind=='ins':
        i1=idx.get(p0); i2=idx.get(p0+1)
        if i1 is not None and i2 is not None and i2==i1+1:
            n=len(alt)-len(ref)
            return ('frameshift',) if n%3 else ('inframe_insertion',)
        return _noncoding(t,aff)
    if kind=='del':
        hits=[idx.get(p) for p in aff]
        inc=[h for h in hits if h is not None]
        if inc:
            n=len(ref)-len(alt)
            return ('frameshift',) if n%3 else ('inframe_deletion',)
        return _noncoding(t,aff)
    # sub
    inc=[p for p in aff if p in idx]
    if inc:
        n=len(ref)-len(alt)
        return ('frameshift',) if n%3 else ('inframe_indel',)
    return _noncoding(t,aff)

def _noncoding(t,aff):
    for (s,e) in exons[t]:
        for p in aff:
            if s<=p<e: return ('UTR',)
    gs=min(s for s,e in exons[t]); ge=max(e for s,e in exons[t])
    for p in aff:
        if gs<=p<ge: return ('intronic',)
    return ('intergenic',)

def codon_of(t,p0):
    idx=cdsidx[t]
    if p0 not in idx: return None
    return idx[p0]//3

def combined_codon_class(t,codon_i,changes):
    c0=codon_i*3
    refcod=cdsseq[t][c0:c0+3]
    altcod=list(refcod)
    for (off,base) in changes.items():
        altcod[off]=base
    altcod=''.join(altcod)
    ra,aa=CODON.get(refcod,'?'),CODON.get(altcod,'?')
    if ra==aa: return 'synonymous'
    if aa=='*': return 'stop_gained'
    return 'missense'

# ---- popfreq
pop={}
import gzip
with gzip.open(POP,'rt') as f:
    header=f.readline()
    for line in f:
        c,p,r,a,af=line.rstrip('\n').split('\t')
        pop[(int(p),r,a)]=float(af)

# ---- panel
panel=set(x.strip() for x in open(PANEL) if x.strip())

# ---- source info (DP/GQ/AD per rid,sample)
srcinfo={}
for line in open(SRC):
    rid,s,dp,gq,ad=line.rstrip('\n').split('\t')
    srcinfo[(int(rid),s)]=(int(dp),int(gq),[int(x) for x in ad.split(',')])

fsrc={}
for line in open(FSRC):
    if line.startswith('pos'): continue
    p,r,a,rid,an=line.rstrip('\n').split('\t')
    fsrc[(int(p),r,a)]=(int(rid),int(an))

# ---- load final vcf
vars=[]
vf=pysam.FastaFile  # noop
vf=pysam.VariantFile(VCF)
for rec in vf:
    pos=rec.pos; ref=rec.ref; alt=rec.alts[0]
    gt={s:rec.samples[s]['GT'] for s in SAMPLES}
    copies={s:(1 if gt[s][0]==1 else 0)+(1 if gt[s][1]==1 else 0) for s in SAMPLES}
    rid,an=fsrc[(pos,ref,alt)]
    usable=True; ab_ok=True
    if rid==0:
        usable=True
    else:
        for s in SAMPLES:
            dp,gq,ad=srcinfo[(rid,s)]
            if dp<10 or gq<20: usable=False
        if copies[KID]==1:
            dp,gq,ad=srcinfo[(rid,KID)]
            if an==0:
                ad_ref=ad[1]; ad_alt=ad[0]
            else:
                ad_ref=ad[0]; ad_alt=ad[an]
            frac=ad_alt/(ad_ref+ad_alt) if (ad_ref+ad_alt)>0 else 0
            if not (0.25<=frac<=0.75): ab_ok=False
    af=pop.get((pos,ref,alt),0.0)
    rare=af<0.001
    # transcripts hit
    thits=[]
    for t in tids:
        cl=consequence(pos,ref,alt,t)
        if cl[0] not in ('intergenic',):
            thits.append((t,cl[0]))
    vars.append(dict(pos=pos,ref=ref,alt=alt,gt=gt,copies=copies,rid=rid,an=an,usable=usable,ab_ok=ab_ok,af=af,rare=rare,thits=thits))
print('variants:',len(vars))

# ---- rule 5: per transcript codon copy combination for proband-carried SNVs
# variant copy assignment
def var_copies(v):
    c=v['copies']
    if c[KID]==2: return ('both',)
    if c[KID]==1:
        if c[MOM]>=1 and c[DAD]==0: return ('mat',)
        if c[DAD]>=1 and c[MOM]==0: return ('pat',)
        return ('none',)
    return ()

for v in vars:
    v['vcopies']=var_copies(v)

# per transcript: collect proband-carried SNVs in CDS
conscache={}
def var_consequence(v,t):
    key=(v['pos'],v['ref'],v['alt'],t)
    if key in conscache: return conscache[key]
    base=consequence(v['pos'],v['ref'],v['alt'],t)[0]
    result=None
    if base in ('missense','synonymous','stop_gained') and v['vcopies']:
        ci=codon_of(t,v['pos']-1)
        if ci is not None:
            copymap={'both':['m','f'],'mat':['m'],'pat':['f'],'none':[]}
            cls={}
            for cp in copymap[v['vcopies'][0] if v['vcopies'][0]!='both' else 'both'] if False else []:
                pass
            # build per copy
            per={}
            copieset={'m':[],'f':[]}
            for w in vars:
                if not w['vcopies']: continue
                if w['pos']==v['pos'] and w['ref']==v['ref'] and w['alt']==v['alt']:
                    wc=v['vcopies'][0]
                else:
                    wc=w['vcopies'][0]
                # only SNVs in CDS of t
                if len(w['ref'])!=1 or len(w['alt'])!=1: continue
                ciw=codon_of(t,w['pos']-1)
                if ciw!=ci: continue
                if wc=='both': copieset['m'].append(w); copieset['f'].append(w)
                elif wc=='mat': copieset['m'].append(w)
                elif wc=='pat': copieset['f'].append(w)
            classes={}
            for cp in ('m','f'):
                ws=copieset[cp]
                if not ws: continue
                if len(ws)==1:
                    classes[cp]=consequence(ws[0]['pos'],ws[0]['ref'],ws[0]['alt'],t)[0]
                else:
                    ch={}
                    for w in ws:
                        i=cdsidx[t][w['pos']-1]
                        ch[i%3]=w['alt'] if strand[t]=='+' else {'A':'T','T':'A','G':'C','C':'G'}[w['alt']]
                    classes[cp]=combined_codon_class(t,ci,ch)
            vc=v['vcopies'][0]
            if vc=='both':
                cm=classes.get('m'); cf=classes.get('f')
                result=cm if cm==cf else (cm+'&'+cf)
            elif vc=='mat':
                result=classes.get('m',base)
            elif vc=='pat':
                result=classes.get('f',base)
            else:
                result=base
    if result is None:
        result=base
    conscache[key]=result
    return result

QUAL={'missense','stop_gained','frameshift','splice_acceptor','splice_donor'}

# per variant: best transcript consequence(s) in panel genes
for v in vars:
    v['panel_hits']=[]
    for t,cl0 in v['thits']:
        gene=mRNA[t]
        if gene not in panel: continue
        cl=var_consequence(v,t)
        # qualifying classes, possibly &-joined
        parts=set(cl.split('&'))
        if parts & QUAL:
            v['panel_hits'].append((gene,cl))

# ---- rules 2-7
reviewed=[]
for v in vars:
    if not v['usable'] or not v['ab_ok'] or not v['rare'] or not v['panel_hits']:
        continue
    c=v['copies']
    if c[KID]==0: continue
    v['models']=[]
    if c[KID]==1 and c[MOM]==0 and c[DAD]==0:
