    reviewed.append(v)
# compound het
bygene=defaultdict(list)
for v in reviewed:
    for gene,cl in v['panel_hits']:
        bygene[gene].append(v)
for gene,vs in bygene.items():
    matonly=[v for v in vs if v['copies'][KID]==1 and v['copies'][MOM]==1 and v['copies'][DAD]==0]
    patonly=[v for v in vs if v['copies'][KID]==1 and v['copies'][DAD]==1 and v['copies'][MOM]==0]
    if matonly and patonly:
        for v in matonly+patonly:
            if 'compound_het' not in v['models']:
                v['models'].append('compound_het')

cand=[v for v in reviewed if v['models']]
print('candidates:',len(cand))
rows=[]
for v in cand:
    for gene,cl in v['panel_hits']:
        for m in v['models']:
            rows.append(('chr22',v['pos'],v['ref'],v['alt'],gene,cl,m))
rows.sort(key=lambda r:(r[1],r[2],r[3],r[4]))
with open(OUT,'w') as f:
    f.write('chrom\tpos\tref\talt\tgene\tconsequence\tmodel\n')
